function wrapLines(s,x,y,size){const words=String(s).split(' '),max=Math.floor(900/size),lines=[''];for(const w of words){if((lines.at(-1)+' '+w).trim().length>max&&lines.at(-1))lines.push(w);else lines[lines.length-1]=(lines.at(-1)+' '+w).trim();}return lines.map((v,i)=>`<tspan x="${x}" y="${y+i*(size+4)}">${esc(v)}</tspan>`).join('');}
import{experimentResult,outputLabel}from './rad1-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const txt=(x,y,s,size=16)=>`<text x="${x}" y="${y}" font-size="${size}" fill="#f8f5ee" text-anchor="middle">${wrapLines(s,x,y,size)}</text>`;
const ball=(x,y,r=13,c='coral')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="url(#rad1-${c})" stroke="#fff" stroke-opacity=".25"/>`;
const line=(x,y,a,b,c='#ed907d',w=3)=>`<path d="M${x} ${y} L${a} ${b}" fill="none" stroke="${c}" stroke-width="${w}"/>`;
const nucleus=(x,y,n=8)=>Array.from({length:n},(_,i)=>ball(x+Math.cos(i*2.4)*Math.sqrt(i)*7,y+Math.sin(i*2.4)*Math.sqrt(i)*7,11,i%2?'teal':'coral')).join('');
export function radiationFigure({kind='atoms',progress=.4,movie=false,a,b,revealed=false,concealed=false}={}){let k=kind.split('-')[0];if(kind.startsWith('half-life'))k='half-life';let p=movie?Math.max(0,Math.min(1,progress)):.6,s='';
if(k==='atoms'){let charge=Number(b||0),A=Number(a||12),phase=p<.5?p*2:(1-p)*2,r=70+50*phase;s+=`<ellipse cx="280" cy="225" rx="140" ry="75" fill="none" stroke="#b8d4d1" opacity=".25"/><circle cx="280" cy="225" r="70" fill="none" stroke="#9ac9c5"/><circle cx="280" cy="225" r="120" fill="none" stroke="#9ac9c5" stroke-dasharray="4 6"/>`+nucleus(280,225,12)+ball(280+r,225,8,'teal')+txt(280,55,'Nucleus enlarged · energy levels schematic',13)+txt(280,345,movie?(p<.5?'Absorb radiation → higher level':'Emit radiation → lower level'):'Carbon: Z = 6; A = '+A)+txt(280,380,revealed?`${A-6} neutrons · ${6-charge} electrons`:'Isotope changes neutrons; ion changes electrons');}
else if(k==='evidence'){let strong=(a||'nuclear')==='nuclear'&&(b||'close')==='close',x=75+410*p,y=230,def=strong&&p>.5?(p-.5)*260:0;s+=`<rect x="265" y="115" width="24" height="225" rx="6" fill="#ed907d" opacity=".35"/>`+nucleus(278,225,8)+line(60,230,270,230,'#9ac9c5')+line(270,230,strong?145:495,strong?80:220,'#9ac9c5')+ball(strong&&p>.5?280-(p-.5)*270:x,y-def,9,'gold')+txt(280,55,'Positive alpha → positive nuclear charge')+txt(280,380,'Most pass through; rare close encounters deflect')+txt(280,410,'Rare deflection exaggerated · not measured frequency',13);}
else if(k==='radiation'){let emission=a||'alpha',barrier=b||'paper',stopped=!(emission==='beta'&&barrier==='paper'),x=110+(stopped?170:350)*p;s+=nucleus(95,230,12)+`<rect x="290" y="120" width="24" height="220" rx="5" fill="#b9c8d5"/>`+ball(x,230,emission==='alpha'?15:7,emission==='alpha'?'coral':'teal')+txt(300,100,barrier)+txt(100,310,emission)+txt(280,380,'Alpha: strong ionisation, short range')+txt(280,410,'Gamma: penetrating; thick shielding reduces intensity',13);}
else if(k==='equations'){let alpha=(a||'alpha')==='alpha',[A,Z]=alpha?[210,84]:[14,6];s+=nucleus(190,220,16)+nucleus(190+110*p,220,alpha?12:16)+(alpha?nucleus(190+250*p,220-95*p,4):ball(190+250*p,220-95*p,6,'teal'))+txt(280,75,alpha?'Single alpha event':'Single beta-minus event')+txt(280,335,`Parent A${A} Z${Z}`)+txt(280,375,revealed||movie?`Daughter A${alpha?A-4:A} Z${alpha?Z-2:Z+1}`:'Balance total A and charge number Z')+txt(280,410,alpha?'Emission: A4 Z2':'Emission: A0 Z−1',15);}
else if(k==='half-life'){let start=Number(a||80),intervals=Number(b||2),t=movie?Math.min(3,p*4):intervals,N=start/2**t;s+=line(65,325,485,325,'#9ac9c5')+line(65,325,65,95,'#9ac9c5');let points=Array.from({length:81},(_,i)=>`${65+i*5},${325-200*2**(-i*3/80)}`).join(' ');s+=`<polyline points="${points}" fill="none" stroke="#ed907d" stroke-width="4"/>`+ball(65+t*400/3,325-200*2**(-t),8,'gold')+txt(280,355,'Elapsed / half-lives',14)+txt(280,70,'Expected population · individual events random')+txt(280,405,revealed||movie?`${t.toFixed(1)} half-lives → ${Number(N.toFixed(1))} expected survivors`:'Halve the surviving population each interval');for(let i=0;i<=3;i++)s+=txt(65+i*400/3,345,String(i),12);}
else if(k==='hazards'){let dust=(a||'dust')==='dust',near=(b||'near')==='near';s+=`<rect x="150" y="245" width="260" height="22" rx="6" fill="#b9c8d5"/>`+nucleus(near?100:30,140,10);if(dust)for(let i=0;i<8;i++)s+=ball(185+i*25,233,5,'coral');for(let i=0;i<4;i++)s+=line(near?115:40,150,near?170+p*130:60,190+i*20,'#ed907d',1);s+=txt(280,65,'Exposure is not deposited source material')+txt(280,320,dust?'Radioactive dust remains on the surface':'Sealed source: no radioactive dust deposited')+txt(280,365,'Time · distance · shielding · containment',15);}
else if(k==='background'){let bg=Number(a||8),total=Number(b||40);for(let i=0;i<20;i++)s+=ball(70+(i*83)%420,110+(i*47)%160,4,i%3?'teal':'coral');s+=`<rect x="190" y="180" width="180" height="90" rx="15" fill="#12283b" stroke="#9ac9c5"/>`+txt(280,220,'Detector',20)+txt(280,250,movie?`${Math.floor(p*total)} illustrative counts`:'Source + background',13)+txt(280,335,`Total ${total} − background ${bg}`)+txt(280,385,revealed?`Source estimate ${total-bg} counts/s`:'Keep time and geometry comparable');}
else if(k==='uses'){let gamma=(b||'gamma')==='gamma';s+=`<rect x="180" y="130" width="200" height="200" rx="60" fill="#ed907d" opacity=".16"/>`+nucleus(280,230,8)+`<rect x="440" y="170" width="45" height="100" rx="10" fill="#9ac9c5" opacity=".7"/>`+line(290,230,gamma?300+150*p:300+20*p,230,gamma?'#e8c780':'#ed907d',4)+txt(280,70,'Emission must match the physical purpose')+txt(460,300,'Detector',13)+txt(280,385,gamma?'Gamma can escape to an external detector':'Alpha deposits energy over a short distance');}
else if(k==='fission'){let q=Math.min(1,p*2);s+=ball(60+110*Math.min(1,p*4),225,6,'teal')+nucleus(200-35*q,225-45*q,10)+nucleus(200+35*q,225+45*q,10);for(let i=0;i<3;i++)s+=ball(210+230*q,225+(i-1)*130*q,6,'teal');s+=nucleus(455,95,12)+nucleus(455,355,12)+txt(280,55,'Absorb neutron → split → further triggers')+txt(280,400,'Not every neutron causes another fission')+txt(280,430,'Branching, sizes and timings illustrative',13);}
else if(k==='fusion'){let q=Math.min(1,p*2);s+=q<1?nucleus(130+120*q,225,2)+nucleus(430-120*q,225,3):nucleus(280,225,4)+ball(300+(p-.5)*300,225-(p-.5)*180,6,'teal');s+=txt(280,70,'²₁H + ³₁H → ⁴₂He + ¹₀n')+txt(280,345,'A: 2 + 3 = 4 + 1')+txt(280,380,'Z: 1 + 1 = 2 + 0')+txt(280,425,'Successful event selected · not collision probability',13);}
if(a&&b&&revealed)s+=txt(280,460,outputLabel(k,experimentResult(k,a,b).value),14);
return `<svg class="shell-diagram rad1-diagram" viewBox="0 0 560 480" role="img" aria-label="${esc(k+' educational model'+(revealed?' with revealed evidence':''))}"><defs>${[['coral','#ffd6bc','#d66f62'],['teal','#c9f1e8','#59989b'],['gold','#fff0b1','#b99a50']].map(([n,c,v])=>`<radialGradient id="rad1-${n}" cx="30%" cy="25%"><stop stop-color="${c}"/><stop offset="1" stop-color="${v}"/></radialGradient>`).join('')}</defs>${s}</svg>`;}
